import{_ as o,o as e,c as t,a3 as s}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Apresentação","description":"","frontmatter":{"title":"Apresentação"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),r={name:"index.md"};function d(n,a,i,c,l,u){return e(),t("div",null,a[0]||(a[0]=[s('<h1 id="manual-do-eploc" tabindex="-1">Manual do eploc <a class="header-anchor" href="#manual-do-eploc" aria-label="Permalink to &quot;Manual do eploc&quot;">​</a></h1><p>O <strong>eploc</strong> é uma extensão gratuita para Google Chrome e Microsoft Edge que acrescenta painéis, atalhos e automações ao <strong>eproc</strong>, ao <strong>SEI</strong>, ao <strong>RUPE</strong> e a páginas do <strong>TJMG</strong>, sem mudar o jeito como esses sistemas funcionam. Cada melhoria é uma funcionalidade separada, que você liga ou desliga quando quiser.</p><p>Este manual explica, para cada funcionalidade, o que ela faz, onde aparece, como usar, quais opções tem e o que ela não faz.</p><h2 id="por-onde-comecar" tabindex="-1">Por onde começar <a class="header-anchor" href="#por-onde-comecar" aria-label="Permalink to &quot;Por onde começar&quot;">​</a></h2><ul><li><strong>Primeira vez?</strong> Siga o <a href="./inicio-rapido">Início rápido</a>: instalação, permissões, conexão com o Google Drive e primeira configuração.</li><li><strong>Procurando um recurso?</strong> Use a busca (no topo da página) ou a lista de <a href="./funcionalidades/">Funcionalidades</a>.</li><li><strong>Dúvidas sobre dados?</strong> Veja <a href="./privacidade">Privacidade e dados</a>.</li><li><strong>Precisa enviar o manual a um tribunal ou a outra instituição?</strong> Baixe a <a href="https://eploc.com.br/manual/eploc-manual.pdf" target="_blank" rel="noreferrer">versão em PDF</a>, com todo o conteúdo deste site.</li></ul><h2 id="como-ler-as-paginas-de-funcionalidade" tabindex="-1">Como ler as páginas de funcionalidade <a class="header-anchor" href="#como-ler-as-paginas-de-funcionalidade" aria-label="Permalink to &quot;Como ler as páginas de funcionalidade&quot;">​</a></h2><p>Toda página de funcionalidade segue o mesmo molde:</p><table tabindex="0"><thead><tr><th>Parte</th><th>O que traz</th></tr></thead><tbody><tr><td>Selos no topo</td><td>Sistema (eproc, RUPE, SEI ou TJMG), plano (<strong>Gratuito</strong> ou <strong>Pro</strong>), versão em que surgiu e se vem ligada ou desligada</td></tr><tr><td>O que faz</td><td>Resumo em 2 ou 3 frases</td></tr><tr><td>Onde aparece</td><td>Sistema e tela</td></tr><tr><td>Passo a passo</td><td>Como usar</td></tr><tr><td>Configurações e opções</td><td>As opções do card da funcionalidade, com o valor padrão</td></tr><tr><td>Observações</td><td>Características, cuidados e o que ela não faz</td></tr></tbody></table><p>O nome de cada página é o mesmo que aparece nas configurações do eploc, para você encontrar o card correspondente com a busca das configurações.</p><div class="tip custom-block"><p class="custom-block-title">Exemplos fictícios</p><p>Todos os números de processo, nomes, CPFs e demais dados usados nos exemplos deste manual são fictícios.</p></div><div class="warning custom-block"><p class="custom-block-title">Confira sempre</p><p>O eploc é um auxílio. A conferência de todos os atos praticados nos sistemas oficiais continua sendo de quem os pratica (veja os <a href="https://eploc.com.br/termos" target="_blank" rel="noreferrer">termos de uso</a>).</p></div>',11)]))}const g=o(r,[["render",d]]);export{m as __pageData,g as default};
